1	import type {ToolDefinition} from '../../types/ai.js';
2	import type {OutgoingMessage} from '../../types/messages.js';
3	import {log} from '../../shared/logger.js';
4	
5	export interface ToolResponse {
6	  result: string;
7	  clientMessages?: OutgoingMessage[];
8	  suppressAssistantResponse?: boolean;
9	}
10	
11	export interface ToolContext {
12	  userId: string | number;
13	  sessionId?: string;
14	  workspaceId?: string | number;
15	  authHeaders?: {
16	    cookie?: string;
17	    authorization?: string;
18	    host?: string;
19	  };
20	}
21	
22	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
23	
24	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
25	  return typeof response === 'string' ? {result: response} : response;
26	}
27	
28	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
29	
30	export interface RegisteredTool {
31	  definition: ToolDefinition;
32	  execute: ToolExecutor;
33	}
34	
35	interface StoredTool {
36	  definitionSource: ToolDefinitionSource;
37	  execute: ToolExecutor;
38	}
39	
40	export class ToolRegistry {
41	  private readonly tools = new Map<string, StoredTool>();
42	
43	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
44	    return typeof source === 'function' ? source() : source;
45	  }
46	
47	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
48	    const resolved = this.resolveDefinition(definition);
49	    this.tools.set(resolved.name, {definitionSource: definition, execute});
50	  }
51	
52	  get(name: string): RegisteredTool | undefined {
53	    const tool = this.tools.get(name);
54	    if (!tool) return undefined;
55	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
56	  }
57	
58	  getDefinitions(): ToolDefinition[] {
59	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
60	  }
61	
62	  getPromptInstructions(): string[] {
63	    return this.getDefinitions()
64	      .filter(t => t.promptInstructions)
65	      .map(t => `${t.name}: ${t.promptInstructions}`);
66	  }
67	
68	  getExamplePrompts(): string[] {
69	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
70	  }
71	
72	  has(name: string): boolean {
73	    return this.tools.has(name);
74	  }
75	
76	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
77	    const tool = this.tools.get(name);
78	    if (!tool) {
79	      log.warn('tool', 'tool not found', {name});
80	      throw new Error(`Unknown tool: ${name}`);
81	    }
82	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
83	    const rawResult = await tool.execute(input, context);
84	    const response = normalizeToolResponse(rawResult);
85	    log.info('tool', 'execution complete', {
86	      name,
87	      rawType: typeof rawResult,
88	      clientMessageCount: response.clientMessages?.length ?? 0,
89	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
90	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
91	    });
92	    return response;
93	  }
94	}
